+<!doctype html>
+<html lang="en">
+<head>
+  <meta charset="utf-8">
+  <meta name="viewport" content="width=device-width, initial-scale=1">
+  <title>Vegan Ramen</title>
+  <style>
+    :root {
+      color-scheme: dark;
+      background: #050607;
+    }
+
+    * {
+      box-sizing: border-box;
+    }
+
+    html,
+    body {
+      width: 100%;
+      height: 100%;
+      margin: 0;
+      overflow: hidden;
+      background:
+        radial-gradient(circle at 50% 65%, rgba(191, 96, 35, 0.18), transparent 34%),
+        radial-gradient(circle at 50% 30%, rgba(79, 38, 23, 0.26), transparent 48%),
+        linear-gradient(180deg, #060708 0%, #0c0806 58%, #040404 100%);
+    }
+
+    canvas {
+      display: block;
+      width: 100vw;
+      height: 100vh;
+      touch-action: none;
+    }
+
+    @media (prefers-reduced-motion: reduce) {
+      canvas {
+        cursor: default;
+      }
+    }
+  </style>
+</head>
+<body>
+  <canvas id="scene" aria-label="A steaming bowl of vegan ramen in a dark atmospheric scene"></canvas>
+  <script>
+    (() => {
+      "use strict";
+
+      const canvas = document.getElementById("scene");
+      const ctx = canvas.getContext("2d", { alpha: false });
+      const reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)");
+      const pointer = { x: 0.5, y: 0.48, tx: 0.5, ty: 0.48, active: false };
+      const DPR_LIMIT = 2;
+      let w = 0;
+      let h = 0;
+      let dpr = 1;
+      let start = performance.now();
+      let lastFrame = 0;
+      let steam = [];
+      let herbs = [];
+
+      function clamp(value, min, max) {
+        return Math.max(min, Math.min(max, value));
+      }
+
+      function lerp(a, b, t) {
+        return a + (b - a) * t;
+      }
+
+      function resize() {
+        dpr = Math.min(window.devicePixelRatio || 1, DPR_LIMIT);
+        w = Math.max(1, window.innerWidth);
+        h = Math.max(1, window.innerHeight);
+        canvas.width = Math.round(w * dpr);
+        canvas.height = Math.round(h * dpr);
+        ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
+        seedParticles();
+      }
+
+      function seedParticles() {
+        const bowl = metrics();
+        const steamCount = reduceMotion.matches ? 18 : 54;
+        const herbCount = reduceMotion.matches ? 18 : 42;
+
+        steam = Array.from({ length: steamCount }, (_, i) => ({
+          seed: i * 91.73,
+          x: (Math.random() - 0.5) * bowl.rx * 1.25,
+          y: Math.random(),
+          width: lerp(10, 34, Math.random()),
+          height: lerp(80, 190, Math.random()),
+          speed: lerp(0.045, 0.13, Math.random()),
+          sway: lerp(8, 30, Math.random()),
+          alpha: lerp(0.05, 0.18, Math.random())
+        }));
+
+        herbs = Array.from({ length: herbCount }, () => {
+          const angle = Math.random() * Math.PI * 2;
+          const radius = Math.sqrt(Math.random());
+          return {
+            x: Math.cos(angle) * bowl.rx * 0.66 * radius,
+            y: Math.sin(angle) * bowl.ry * 0.52 * radius,
+            r: lerp(1.4, 3.7, Math.random()),
+            rot: Math.random() * Math.PI,
+            green: Math.random()
+          };
+        });
+      }
+
+      function metrics() {
+        const s = Math.min(w, h);
+        const scale = clamp(s / 760, 0.58, 1.22);
+        const cx = w * 0.5;
+        const cy = h * 0.62;
+        return {
+          s,
+          scale,
+          cx,
+          cy,
+          rx: Math.min(w * 0.38, 315 * scale),
+          ry: Math.min(h * 0.18, 122 * scale),
+          bowlH: Math.min(h * 0.24, 176 * scale)
+        };
+      }
+
+      function ellipsePath(x, y, rx, ry) {
+        ctx.beginPath();
+        ctx.ellipse(x, y, rx, ry, 0, 0, Math.PI * 2);
+      }
+
+      function background(t, bowl, influence) {
+        const warmX = bowl.cx + influence.x * 45;
+        const warmY = bowl.cy - bowl.ry * 0.35 + influence.y * 24;
+        const room = ctx.createRadialGradient(warmX, warmY, 0, warmX, warmY, Math.max(w, h) * 0.72);
+        room.addColorStop(0, "#2d160d");
+        room.addColorStop(0.28, "#120c09");
+        room.addColorStop(0.68, "#070707");
+        room.addColorStop(1, "#030303");
+        ctx.fillStyle = room;
+        ctx.fillRect(0, 0, w, h);
+
+        const pulse = reduceMotion.matches ? 0.7 : 0.7 + Math.sin(t * 1.2) * 0.08;
+        const halo = ctx.createRadialGradient(warmX, warmY, 0, warmX, warmY, bowl.rx * 2.5);
+        halo.addColorStop(0, `rgba(236, 119, 41, ${0.18 * pulse})`);
+        halo.addColorStop(0.36, `rgba(142, 70, 30, ${0.1 * pulse})`);
+        halo.addColorStop(1, "rgba(0, 0, 0, 0)");
+        ctx.fillStyle = halo;
+        ctx.fillRect(0, 0, w, h);
+
+        const vignette = ctx.createRadialGradient(w * 0.5, h * 0.54, Math.min(w, h) * 0.15, w * 0.5, h * 0.54, Math.max(w, h) * 0.74);
+        vignette.addColorStop(0, "rgba(0,0,0,0)");
+        vignette.addColorStop(1, "rgba(0,0,0,0.72)");
+        ctx.fillStyle = vignette;
+        ctx.fillRect(0, 0, w, h);
+      }
+
+      function drawSteam(t, bowl, influence) {
+        ctx.save();
+        ctx.globalCompositeOperation = "screen";
+        ctx.lineCap = "round";
+        for (const p of steam) {
+          const progress = reduceMotion.matches ? p.y : (p.y + t * p.speed) % 1;
+          const rise = progress * p.height;
+          const baseX = bowl.cx + p.x + influence.x * 38 * (1 - progress);
+          const baseY = bowl.cy - bowl.ry * 0.55 - rise;
+          const fade = Math.sin(progress * Math.PI);
+          const drift = Math.sin(t * 1.3 + p.seed + progress * 5.6) * p.sway + influence.x * 55 * progress;
+
+          const grad = ctx.createLinearGradient(baseX, baseY + 58, baseX + drift, baseY - 44);
+          grad.addColorStop(0, "rgba(255, 222, 178, 0)");
+          grad.addColorStop(0.42, `rgba(255, 226, 194, ${p.alpha * fade})`);
+          grad.addColorStop(1, "rgba(255, 255, 255, 0)");
+          ctx.strokeStyle = grad;
+          ctx.lineWidth = p.width * (0.16 + progress * 0.2);
+          ctx.beginPath();
+          ctx.moveTo(baseX, baseY + 54);
+          ctx.bezierCurveTo(
+            baseX - p.sway * 0.35 + influence.x * 18,
+            baseY + 20,
+            baseX + drift * 0.45,
+            baseY - 16,
+            baseX + drift,
+            baseY - 64
+          );
+          ctx.stroke();
+        }
+        ctx.restore();
+      }
+
+      function drawShadow(bowl) {
+        const shadow = ctx.createRadialGradient(bowl.cx, bowl.cy + bowl.bowlH * 0.58, 0, bowl.cx, bowl.cy + bowl.bowlH * 0.58, bowl.rx * 1.35);
+        shadow.addColorStop(0, "rgba(0,0,0,0.62)");
+        shadow.addColorStop(0.6, "rgba(0,0,0,0.36)");
+        shadow.addColorStop(1, "rgba(0,0,0,0)");
+        ctx.fillStyle = shadow;
+        ellipsePath(bowl.cx, bowl.cy + bowl.bowlH * 0.58, bowl.rx * 1.25, bowl.ry * 0.62);
+        ctx.fill();
+      }
+
+      function drawBowl(t, bowl, influence) {
+        drawShadow(bowl);
+
+        const body = ctx.createLinearGradient(0, bowl.cy - bowl.ry * 0.1, 0, bowl.cy + bowl.bowlH);
+        body.addColorStop(0, "#2d3032");
+        body.addColorStop(0.42, "#151719");
+        body.addColorStop(1, "#060707");
+        ctx.fillStyle = body;
+        ctx.beginPath();
+        ctx.moveTo(bowl.cx - bowl.rx * 0.98, bowl.cy);
+        ctx.quadraticCurveTo(bowl.cx - bowl.rx * 0.72, bowl.cy + bowl.bowlH * 1.07, bowl.cx, bowl.cy + bowl.bowlH);
+        ctx.quadraticCurveTo(bowl.cx + bowl.rx * 0.72, bowl.cy + bowl.bowlH * 1.07, bowl.cx + bowl.rx * 0.98, bowl.cy);
+        ctx.closePath();
+        ctx.fill();
+
+        ctx.strokeStyle = "rgba(255,255,255,0.12)";
+        ctx.lineWidth = 2 * bowl.scale;
+        ctx.stroke();
+
+        const rim = ctx.createLinearGradient(0, bowl.cy - bowl.ry, 0, bowl.cy + bowl.ry);
+        rim.addColorStop(0, "#5b5c58");
+        rim.addColorStop(0.42, "#2a2b2b");
+        rim.addColorStop(1, "#0d0e0f");
+        ctx.fillStyle = rim;
+        ellipsePath(bowl.cx, bowl.cy, bowl.rx, bowl.ry);
+        ctx.fill();
+
+        ctx.save();
+        ellipsePath(bowl.cx, bowl.cy - bowl.ry * 0.05, bowl.rx * 0.88, bowl.ry * 0.76);
+        ctx.clip();
+        drawBroth(t, bowl, influence);
+        drawNoodles(t, bowl, influence);
+        drawToppings(t, bowl, influence);
+        ctx.restore();
+
+        ctx.strokeStyle = "rgba(255, 238, 206, 0.3)";
+        ctx.lineWidth = 3.5 * bowl.scale;
+        ellipsePath(bowl.cx, bowl.cy - bowl.ry * 0.02, bowl.rx * 0.93, bowl.ry * 0.83);
+        ctx.stroke();
+
+        const shine = ctx.createLinearGradient(bowl.cx - bowl.rx, bowl.cy, bowl.cx + bowl.rx, bowl.cy + bowl.bowlH * 0.8);
+        shine.addColorStop(0, "rgba(255,255,255,0)");
+        shine.addColorStop(0.27, "rgba(255,255,255,0.09)");
+        shine.addColorStop(0.38, "rgba(255,255,255,0.02)");
+        shine.addColorStop(1, "rgba(255,255,255,0)");
+        ctx.fillStyle = shine;
+        ctx.beginPath();
+        ctx.moveTo(bowl.cx - bowl.rx * 0.86, bowl.cy + bowl.ry * 0.16);
+        ctx.quadraticCurveTo(bowl.cx - bowl.rx * 0.42, bowl.cy + bowl.bowlH * 0.85, bowl.cx - bowl.rx * 0.08, bowl.cy + bowl.bowlH * 0.9);
+        ctx.quadraticCurveTo(bowl.cx - bowl.rx * 0.2, bowl.cy + bowl.bowlH * 0.46, bowl.cx - bowl.rx * 0.48, bowl.cy + bowl.ry * 0.2);
+        ctx.closePath();
+        ctx.fill();
+      }
+
+      function drawBroth(t, bowl, influence) {
+        const swirl = reduceMotion.matches ? 0 : Math.sin(t * 1.7) * 5;
+        const broth = ctx.createRadialGradient(
+          bowl.cx + influence.x * 26,
+          bowl.cy - bowl.ry * 0.25 + influence.y * 14,
+          0,
+          bowl.cx,
+          bowl.cy,
+          bowl.rx
+        );
+        broth.addColorStop(0, "#f19a38");
+        broth.addColorStop(0.3, "#b95422");
+        broth.addColorStop(0.72, "#592513");
+        broth.addColorStop(1, "#27100b");
+        ctx.fillStyle = broth;
+        ellipsePath(bowl.cx, bowl.cy - bowl.ry * 0.05, bowl.rx * 0.87, bowl.ry * 0.73);
+        ctx.fill();
+
+        ctx.globalCompositeOperation = "screen";
+        for (let i = 0; i < 7; i++) {
+          const a = i * 0.9 + t * 0.22;
+          const x = bowl.cx + Math.cos(a) * bowl.rx * (0.18 + i * 0.065) + influence.x * 14;
+          const y = bowl.cy - bowl.ry * 0.08 + Math.sin(a * 1.7) * bowl.ry * 0.16 + swirl;
+          ctx.strokeStyle = `rgba(255, 185, 83, ${0.09 - i * 0.006})`;
+          ctx.lineWidth = bowl.scale * (8 - i * 0.45);
+          ctx.beginPath();
+          ctx.ellipse(x, y, bowl.rx * (0.16 + i * 0.04), bowl.ry * (0.035 + i * 0.011), a * 0.12, 0, Math.PI * 2);
+          ctx.stroke();
+        }
+        ctx.globalCompositeOperation = "source-over";
+      }
+
+      function drawNoodles(t, bowl, influence) {
+        ctx.save();
+        ctx.lineCap = "round";
+        ctx.lineJoin = "round";
+        for (let i = 0; i < 19; i++) {
+          const y = bowl.cy - bowl.ry * 0.27 + (i % 7) * bowl.ry * 0.095;
+          const x0 = bowl.cx - bowl.rx * (0.54 - (i % 3) * 0.05);
+          const phase = t * (reduceMotion.matches ? 0 : 1.05) + i * 0.72;
+          ctx.strokeStyle = i % 4 === 0 ? "#f5cc76" : "#e8b95f";
+          ctx.lineWidth = bowl.scale * (5.2 + (i % 3) * 0.6);
+          ctx.beginPath();
+          ctx.moveTo(x0, y);
+          for (let j = 1; j <= 6; j++) {
+            const x = x0 + j * bowl.rx * 0.18;
+            const yy = y + Math.sin(phase + j * 1.25) * bowl.ry * 0.065 + influence.y * 5;
+            ctx.lineTo(x, yy);
+          }
+          ctx.stroke();
+
+          ctx.strokeStyle = "rgba(84, 38, 11, 0.26)";
+          ctx.lineWidth = bowl.scale * 1.2;
+          ctx.stroke();
+        }
+        ctx.restore();
+      }
+
+      function drawToppings(t, bowl, influence) {
+        const bob = reduceMotion.matches ? 0 : Math.sin(t * 1.6) * bowl.scale * 2.2;
+        drawMushroom(bowl.cx - bowl.rx * 0.28 + influence.x * 5, bowl.cy - bowl.ry * 0.14 + bob, bowl.scale, -0.18);
+        drawMushroom(bowl.cx + bowl.rx * 0.22 + influence.x * 4, bowl.cy - bowl.ry * 0.28 - bob * 0.5, bowl.scale * 0.92, 0.25);
+        drawBokChoy(bowl.cx + bowl.rx * 0.39, bowl.cy + bowl.ry * 0.02 + bob * 0.35, bowl.scale, 0.3);
+        drawBokChoy(bowl.cx - bowl.rx * 0.46, bowl.cy - bowl.ry * 0.03 - bob * 0.25, bowl.scale * 0.86, -0.34);
+        drawCorn(bowl.cx + bowl.rx * 0.02, bowl.cy + bowl.ry * 0.22, bowl.scale);
+
+        for (const herb of herbs) {
+          ctx.save();
+          ctx.translate(bowl.cx + herb.x + influence.x * 3, bowl.cy - bowl.ry * 0.06 + herb.y + influence.y * 2);
+          ctx.rotate(herb.rot + (reduceMotion.matches ? 0 : Math.sin(t + herb.x) * 0.1));
+          ctx.fillStyle = herb.green > 0.48 ? "#6fb24f" : "#3e8e45";
+          ctx.beginPath();
+          ctx.ellipse(0, 0, herb.r * 2.2 * bowl.scale, herb.r * bowl.scale, 0, 0, Math.PI * 2);
+          ctx.fill();
+          ctx.restore();
+        }
+      }
+
+      function drawMushroom(x, y, scale, rot) {
+        ctx.save();
+        ctx.translate(x, y);
+        ctx.rotate(rot);
+        ctx.scale(scale, scale);
+        ctx.fillStyle = "#efe2c3";
+        ctx.beginPath();
+        ctx.roundRect(-26, -7, 52, 18, 8);
+        ctx.fill();
+        ctx.fillStyle = "#9b6a45";
+        ctx.beginPath();
+        ctx.ellipse(0, -8, 34, 17, 0, Math.PI, Math.PI * 2);
+        ctx.closePath();
+        ctx.fill();
+        ctx.strokeStyle = "rgba(78,42,24,0.55)";
+        ctx.lineWidth = 2;
+        for (let i = -2; i <= 2; i++) {
+          ctx.beginPath();
+          ctx.moveTo(i * 9, -4);
+          ctx.lineTo(i * 5, 8);
+          ctx.stroke();
+        }
+        ctx.restore();
+      }
+
+      function drawBokChoy(x, y, scale, rot) {
+        ctx.save();
+        ctx.translate(x, y);
+        ctx.rotate(rot);
+        ctx.scale(scale, scale);
+        ctx.fillStyle = "#d6ead0";
+        ctx.beginPath();
+        ctx.ellipse(0, 11, 13, 32, -0.22, 0, Math.PI * 2);
+        ctx.fill();
+        ctx.fillStyle = "#4d9a52";
+        for (let i = -1; i <= 1; i++) {
+          ctx.save();
+          ctx.rotate(i * 0.44);
+          ctx.beginPath();
+          ctx.ellipse(i * 14, -14, 15, 34, i * 0.18, 0, Math.PI * 2);
+          ctx.fill();
+          ctx.restore();
+        }
+        ctx.strokeStyle = "rgba(232,255,221,0.45)";
+        ctx.lineWidth = 2;
+        ctx.beginPath();
+        ctx.moveTo(0, 28);
+        ctx.lineTo(0, -31);
+        ctx.stroke();
+        ctx.restore();
+      }
+
+      function drawCorn(x, y, scale) {
+        ctx.save();
+        ctx.translate(x, y);
+        ctx.scale(scale, scale);
+        for (let row = 0; row < 4; row++) {
+          for (let col = 0; col < 6; col++) {
+            ctx.fillStyle = (row + col) % 2 ? "#ffd45d" : "#f7b83e";
+            ctx.beginPath();
+            ctx.ellipse((col - 2.5) * 8, (row - 1.5) * 7, 4.1, 3.6, 0.15, 0, Math.PI * 2);
+            ctx.fill();
+          }
+        }
+        ctx.restore();
+      }
+
+      function draw(t) {
+        const bowl = metrics();
+        pointer.x = lerp(pointer.x, pointer.tx, reduceMotion.matches ? 1 : 0.055);
+        pointer.y = lerp(pointer.y, pointer.ty, reduceMotion.matches ? 1 : 0.055);
+        const influence = {
+          x: clamp((pointer.x - 0.5) * 2, -1, 1),
+          y: clamp((pointer.y - 0.5) * 2, -1, 1)
+        };
+
+        background(t, bowl, influence);
+        drawSteam(t, bowl, influence);
+        drawBowl(t, bowl, influence);
+
+        const glow = ctx.createRadialGradient(bowl.cx, bowl.cy - bowl.ry * 0.18, 0, bowl.cx, bowl.cy - bowl.ry * 0.18, bowl.rx * 0.78);
+        glow.addColorStop(0, "rgba(255, 157, 53, 0.16)");
+        glow.addColorStop(1, "rgba(255, 157, 53, 0)");
+        ctx.globalCompositeOperation = "screen";
+        ctx.fillStyle = glow;
+        ellipsePath(bowl.cx, bowl.cy - bowl.ry * 0.15, bowl.rx * 0.8, bowl.ry * 0.65);
+        ctx.fill();
+        ctx.globalCompositeOperation = "source-over";
+      }
+
+      function frame(now) {
+        const fpsCap = reduceMotion.matches ? 8 : 60;
+        if (now - lastFrame > 1000 / fpsCap) {
+          const t = reduceMotion.matches ? 0.35 : (now - start) / 1000;
+          draw(t);
+          lastFrame = now;
+        }
+        requestAnimationFrame(frame);
+      }
+
+      function setPointer(clientX, clientY, active) {
+        pointer.tx = clamp(clientX / w, 0, 1);
+        pointer.ty = clamp(clientY / h, 0, 1);
+        pointer.active = active;
+      }
+
+      window.addEventListener("resize", resize);
+      window.addEventListener("pointermove", (event) => setPointer(event.clientX, event.clientY, true), { passive: true });
+      window.addEventListener("pointerleave", () => {
+        pointer.tx = 0.5;
+        pointer.ty = 0.48;
+        pointer.active = false;
+      });
+      reduceMotion.addEventListener("change", () => {
+        start = performance.now();
+        seedParticles();
+      });
+
+      resize();
+      requestAnimationFrame(frame);
+    })();
+  </script>
+</body>
+</html>

