+
+        herbs = Array.from({ length: herbCount }, () => {
+          const angle = Math.random() * Math.PI * 2;
+          const radius = Math.sqrt(Math.random());
+          return {
+            x: Math.cos(angle) * bowl.rx * 0.66 * radius,
+            y: Math.sin(angle) * bowl.ry * 0.52 * radius,
+            r: lerp(1.4, 3.7, Math.random()),
