+      }
+
+      function drawMushroom(x, y, scale, rot) {
+        ctx.save();
+        ctx.translate(x, y);
+        ctx.rotate(rot);
+        ctx.scale(scale, scale);
+        ctx.fillStyle = "#efe2c3";
